package com.blokqr.app.crypto

import com.blokqr.app.model.SignedVerdictDto
import kotlinx.serialization.json.Json
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.Base64

/**
 * Preuve que la LIAISON DU RAPPORT est réelle (correctif C4).
 *
 * Le verdict (safe/malicious) et le score étaient déjà authentifiés ; ce test
 * verrouille le reste : destination finale, chaîne de redirections, raisons et
 * CAPTURE d'écran. VerdictVerifier recalcule SHA-256 sur les octets exacts de
 * report_canonical et le compare à report_sha256 (signé). Un attaquant qui
 * altère le rapport SANS toucher au verdict signé doit être détecté.
 *
 * Vecteur produit par le serveur (PQClean + Ed25519), expiration lointaine pour
 * un résultat déterministe. Exécution : ./gradlew test
 */
class VerdictBindingTest {

    private val json = Json { ignoreUnknownKeys = true }

    private val nonce = "00112233445566778899aabbccddeeff"
    private val keyId = "3308e2a8e672a800"
    private val edPubB64 = "14lQw9132w0PcngtTStCHrd4YOTx+QNGnSttjF4UZuw="
    private val mldsaPubB64 = ""
    private val nowEpoch = 1780272000L
    private val verdictJson = String(Base64.getDecoder().decode(""), Charsets.UTF_8)

    private fun trusted() = KeyManifest.TrustedKeys(keyId, edPubB64, mldsaPubB64, "")

    @Test
    fun accepte_un_verdict_et_un_rapport_authentiques() {
        val dto = json.decodeFromString(SignedVerdictDto.serializer(), verdictJson)
        val out = VerdictVerifier.verify(dto, nonce, trusted(), requirePq = true, nowEpochSeconds = nowEpoch)
        assertTrue("Devrait être vérifié, raison=${out.reason}", out.verified)
    }

    @Test
    fun rejette_un_rapport_falsifie_alors_que_le_verdict_reste_signe() {
        // Un MitM modifie la destination affichée dans report_canonical (le
        // canonique SIGNÉ ne contient que le hash, donc les signatures restent valides) :
        // seule la liaison report_sha256 doit faire échouer la vérification.
        val tampered = verdictJson.replace("exemple.test", "evil.test")
        assertTrue("'exemple.test' doit être présent (dans report_canonical).", tampered != verdictJson)
        val dto = json.decodeFromString(SignedVerdictDto.serializer(), tampered)
        val out = VerdictVerifier.verify(dto, nonce, trusted(), requirePq = true, nowEpochSeconds = nowEpoch)
        assertFalse("Un rapport altéré doit être REJETÉ par la liaison report_sha256.", out.verified)
    }
}
